/*SELECT FROM [dbo].[OINM] T1 INNER JOIN OWHS T2 ON T2.WhsCode=T1.Warehouse*/DECLARE @StartDate NVARCHAR(20);DECLARE @EndDate NVARCHAR(20);Declare  @Whscode NVARCHAR(50);Declare  @StartItemCode nvarchar(50);declare  @EndItemCode nvarchar(50)/* WHERE */SET @StartDate =/* T1.DocDate */ N'[%0]';SET @EndDate =/* T1.DocDate */ N'[%1]';set  @Whscode =/*   t1.Warehouse*/N'[%2]';set  @StartItemCode =/*  t1.ItemCode*/N'[%3]';set  @EndItemCode =/* t1.ItemCode*/N'[%4]';if len(@Whscode )=0 set @Whscode =nullif len(@StartItemCode)=0 set @StartItemCode =nullif len(@EndItemCode )=0 set @EndItemCode =nullSELECT         tmp.Warehouse,         (         SELECT Whsname         FROM   owhs         WHERE  whscode=tmp.Warehouse        ) 'WH-name', 		        tmp.ItemCode,        tmp.ItemName,        T9.ItmsGrpCod AS ItemGroupCode,T10.ItmsGrpNam AS ItemGroupName,        T9.InvntryUom,                   SUM(tmp.BeginQty) AS [Opening Qty],        SUM(tmp.BeginBalance)[Opening Value],        SUM(tmp.InQty) AS [Input Qty],        SUM(tmp.InBalance) AS [Input Value],        SUM(tmp.OutQty) AS [Output Qty],        SUM(tmp.OutBalance) AS [Output Value],        (SUM(tmp.BeginQty) + SUM(tmp.InQty) - SUM(tmp.OutQty)) AS [Ending Qty],        (SUM(tmp.BeginBalance) + SUM(tmp.InBalance) - SUM(tmp.OutBalance)) AS [Ending Value]FROM    (         SELECT T0.ItemCode ItemCode,                T1.ItemName ItemName,                T0.Warehouse,                0 BeginQty,                0 BeginBalance,                0 InQty,                SUM(T0.TransValue) InBalance,                0 OutQty,                0 OutBalance         FROM   OINM T0         INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode         WHERE  (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'') AND T0.TransValue>0         GROUP BY T0.ItemCode,                T1.ItemName,                T0.Warehouse         UNION ALL         SELECT T0.ItemCode ItemCode,                T1.ItemName ItemName,                T0.Warehouse,                0 BeginQty,                0 BeginBalance,                0,                0,                0,                -SUM(T0.TransValue) OutBalance         FROM   OINM T0         INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode         WHERE  (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'') AND T0.TransValue<0         GROUP BY T0.ItemCode,                T1.ItemName,                T0.Warehouse         UNION ALL         SELECT T0.ItemCode ItemCode,                T1.ItemName ItemName,                T0.Warehouse,                0 BeginQty,                0 BeginBalance,                SUM(T0.InQty) InQty,                0,                SUM(T0.OutQty) OutQty,                0         FROM   OINM T0         INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode         WHERE  (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'')         GROUP BY T0.ItemCode,                T1.ItemName,                T0.Warehouse         UNION ALL         SELECT T0.ItemCode ItemCode,                T1.ItemName,                T0.Warehouse,                (SUM(T0.InQty) - SUM(T0.OutQty)) AS BeginQty,                SUM(T0.TransValue) AS BeginBalance,                0,                0,                0,                0         FROM   OINM T0         INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode         WHERE  T0.[DocDate]<@StartDate         GROUP BY T0.ItemCode,                T1.ItemName,                T0.Warehouse        ) tmp,        OITM T9,        OITB T10WHERE   tmp.ItemCode=T9.ItemCode and (tmp.Warehouse=@Whscode  or @Whscode  is null) and ((tmp.ItemCode>=@startItemcode or @startItemcode is null)   and (tmp.itemcode<=@enditemcode or @enditemcode is null))AND T9.ItmsGrpCod = T10.ItmsGrpCodGROUP BY tmp.ItemCode,        tmp.ItemName,        T9.Spec,    T9.InvntryUom,        tmp.Warehouse        ,T9.ItmsGrpCod,T10.ItmsGrpNamORDER BY tmp.ItemCode;